<?php
namespace App\Form\Admin\Suppliers;
use App\Application\Suppliers\SupplierBranchData; use App\Form\Admin\Clients\{ClientBranchAddressEntryType,ClientPhoneEntryType}; use Symfony\Component\Form\AbstractType; use Symfony\Component\Form\Extension\Core\Type\{CheckboxType,CollectionType,EmailType,HiddenType,TextareaType,TextType}; use Symfony\Component\Form\FormBuilderInterface; use Symfony\Component\OptionsResolver\OptionsResolver;
final class SupplierBranchEntryType extends AbstractType {public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('id',HiddenType::class)->add('code',TextType::class,['label'=>'Código'])->add('name',TextType::class,['label'=>'Nombre de sucursal'])->add('email',EmailType::class,['label'=>'Correo general','required'=>false])->add('notes',TextareaType::class,['label'=>'Notas','required'=>false])->add('isMain',CheckboxType::class,['label'=>'Sucursal principal','required'=>false])->add('addresses',CollectionType::class,['label'=>'Domicilios','entry_type'=>ClientBranchAddressEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype_name'=>'__supplier_address__'])->add('phones',CollectionType::class,['label'=>'Teléfonos y fax','entry_type'=>ClientPhoneEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype_name'=>'__supplier_branch_phone__'])->add('contacts',CollectionType::class,['label'=>'Contactos','entry_type'=>SupplierInlineContactEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype_name'=>'__supplier_contact__']);}public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>SupplierBranchData::class]);}}
